// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Private_Bank} from "../src/Private_Bank.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Private_Bank c;

    function setUp() public {
        c = new Private_Bank(address(this));
    }

    function _run(address sender, uint256 amount) internal {
        amount = bound(amount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= amount);
        vm.assume(amount < c.MinDeposit());
        uint256 before;
        try c.balances(sender) returns (uint256 __r) { before = __r; } catch { return; }
        uint256 beforeSelf;
        try c.balances(address(this)) returns (uint256 __r) { beforeSelf = __r; } catch { return; }
        try c.Deposit{value: amount}() {} catch { return; }
        uint256 afterSelf;
        try c.balances(address(this)) returns (uint256 __r) { afterSelf = __r; } catch { return; }
        assertTrue(afterSelf == beforeSelf);
    }

    function testFuzz_run(address sender, uint256 amount) public {
        _run(sender, amount);
    }

    receive() external payable {}
}
